using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class BDServices {
 const string E="Assets/Afrer_Seconds/05.Model/Environment/B2/";static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/B2_DetailMezzanine/";static string O=>R+"/Docs/Review/2026-11-10_B2_DetailMezzanine/";
 static Scene Check(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_B2_Circular.unity"))throw new Exception("Saved B2 required");return s;}
 static GameObject Group(string n,Transform p){var g=new GameObject(n);g.transform.SetParent(p,false);return g;}
 static GameObject Put(string n,string file,Transform parent,Vector3 pos,Quaternion rot){var src=AssetDatabase.LoadAssetAtPath<GameObject>(E+file+".fbx");if(!src)throw new Exception("Missing "+file);var g=(GameObject)PrefabUtility.InstantiatePrefab(src,parent);g.name=n;g.transform.localPosition=pos;g.transform.localRotation=rot;return g;}
 static List<Vector3> Points(JToken t)=>t["path"].Select(v=>new Vector3((float)v[0],0,-(float)v[1])).ToList();
 static Vector3 At(List<Vector3> ps,float d){for(int i=1;i<ps.Count;i++){float l=Vector3.Distance(ps[i-1],ps[i]);if(d<=l)return Vector3.Lerp(ps[i-1],ps[i],Mathf.Max(0,d/l));d-=l;}return ps.Last();}
 static void Save(Scene s){foreach(var root in s.GetRootGameObjects().Where(g=>g.name.StartsWith("B2_")))foreach(var t in root.GetComponentsInChildren<Transform>(true))if(PrefabUtility.IsPartOfPrefabInstance(t)){PrefabUtility.RecordPrefabInstancePropertyModifications(t);PrefabUtility.RecordPrefabInstancePropertyModifications(t.gameObject);foreach(var c in t.GetComponents<Component>())if(c)PrefabUtility.RecordPrefabInstancePropertyModifications(c);}Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);}
 public static object Import(){AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);var mats=AssetDatabase.FindAssets("t:Material",new[]{E+"Materials"}).Select(AssetDatabase.GUIDToAssetPath).Select(AssetDatabase.LoadAssetAtPath<Material>).Where(m=>m.name.StartsWith("BCM_")).ToDictionary(m=>"B4O_"+m.name.Substring(4));foreach(string n in new[]{"Pipe","PipeRed"})mats["BM_"+n]=AssetDatabase.LoadAssetAtPath<Material>(E+"Materials/BM_"+n+".mat");mats["B2M_RedLamp"]=AssetDatabase.LoadAssetAtPath<Material>(E+"Materials/BD_RedLens.mat");int count=0;foreach(var p in Directory.GetFiles(E,"BD_*.fbx").Where(p=>p.Contains("UpperProcessLines")||p.Contains("RoundBulkhead")||p.Contains("ServicePendant")||p.Contains("PendantSuspension")).Select(p=>p.Replace('\\','/'))){var mi=(ModelImporter)AssetImporter.GetAtPath(p);mi.importAnimation=false;mi.importLights=false;mi.importCameras=false;mi.isReadable=true;mi.importNormals=ModelImporterNormals.Import;foreach(var kv in mats)mi.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),kv.Key),kv.Value);mi.SaveAndReimport();count++;}AssetDatabase.SaveAssets();return new{models=count};}
 static Light Bulb(Transform p,bool pendant,float intensity,float range){var l=Group("RedLightSource",p).AddComponent<Light>();l.transform.localPosition=pendant?new Vector3(0,-.34f,0):new Vector3(0,0,.22f);l.transform.localRotation=pendant?Quaternion.Euler(90,0,0):Quaternion.identity;l.type=pendant?LightType.Spot:LightType.Point;l.spotAngle=115;l.innerSpotAngle=70;l.color=new Color(1,.11f,.045f);l.intensity=intensity;l.range=range;l.shadows=LightShadows.None;return l;}
 public static object Run(){var s=Check();var network=s.GetRootGameObjects().Single(g=>g.name=="B2_MachineryNetwork").transform;var detail=network.Find("B2_DetailPass");if(detail.Find("UpperProcessServices"))throw new Exception("Already applied");var pipes=Group("UpperProcessServices",detail).transform;var data=JObject.Parse(File.ReadAllText(H+"layout.json"));foreach(var t in data["tunnels"]){string id=(string)t["id"];var g=Put("B2_"+id+"_UpperSupplyReturn", "BD_"+id+"_UpperProcessLines",pipes,Vector3.zero,Quaternion.identity);foreach(var mf in g.GetComponentsInChildren<MeshFilter>())mf.gameObject.AddComponent<MeshCollider>().sharedMesh=mf.sharedMesh;}
 int before=s.GetRootGameObjects().Where(g=>g.name.StartsWith("B2_")).SelectMany(g=>g.GetComponentsInChildren<Light>()).Count();detail.Find("RedIndustrialLighting").gameObject.SetActive(false);
 // Remove remaining bar fixtures; preserve low indirect bounce and disable the fixture housing too.
 foreach(var l in s.GetRootGameObjects().Where(g=>g.name.StartsWith("B2_")).SelectMany(g=>g.GetComponentsInChildren<Light>()).ToArray()){if(l.name.Contains("Bounce")||l.name.Contains("Fill")){l.color=new Color(1,.14f,.07f);l.intensity=.24f;}else l.transform.parent.gameObject.SetActive(false);}
 var lighting=Group("B2_ProcessLighting",detail).transform;var plan=JObject.Parse(File.ReadAllText(R+"/SourceAssets/B2_FullFloor/plan.json"));int corridor=0,wall=0,pendants=0,cores=0;
 foreach(var t in plan["tunnels"]){string id=((string)t["id"]).Split('-')[1];var ps=Points(t);float len=0;for(int i=1;i<ps.Count;i++)len+=Vector3.Distance(ps[i-1],ps[i]);int n=Mathf.Max(1,Mathf.RoundToInt((len-5)/9.5f));for(int i=0;i<n;i++){float d=n==1?len*.5f:2.8f+(len-5.6f)*i/(n-1);var p=At(ps,d);var dir=(At(ps,d+.04f)-At(ps,d-.04f)).normalized;var right=Vector3.Cross(Vector3.up,dir);int sign=i%2==0?1:-1;var g=Put("B2_"+id+"_PipeBulkhead_"+i,"BD_RoundBulkhead",lighting,p+right*sign*2.31f+Vector3.up*1.95f,Quaternion.LookRotation(-right*sign));Bulb(g.transform,false,1.65f,8);corridor++;}}
 foreach(var r in plan["rooms"]){string id=(string)r["id"];float rad=(float)r["r"];var center=new Vector3((float)r["x"],0,-(float)r["v"]);if((string)r["kind"]=="core"){int levels=id=="VL"?1:8;for(int k=0;k<levels;k++){float y=id=="VL"?3:2+k*2;int sign=k%2==0?-1:1;var g=Put("B2_"+id+"_ShaftBulkhead_"+k,"BD_RoundBulkhead",lighting,center+new Vector3(sign*4.78f,y,0),Quaternion.LookRotation(new Vector3(-sign,0,0)));Bulb(g.transform,false,2.1f,8);cores++;}continue;}
 for(int i=0;i<3;i++){float a=(30+120*i)*Mathf.Deg2Rad;float rr=rad*.40f;var p=center+new Vector3(Mathf.Cos(a)*rr,0,Mathf.Sin(a)*rr);float y=id=="C02"?6.3f:4.6f;float roof=Mathf.Sqrt(rad*rad-rr*rr)-.09f;var g=Put("B2_"+id+"_Pendant_"+i,"BD_ServicePendant",lighting,p+Vector3.up*y,Quaternion.identity);var cable=Put(g.name+"_Suspension","BD_PendantSuspension",lighting,p+Vector3.up*(y+.4f),Quaternion.identity);cable.transform.localScale=new Vector3(1,roof-y-.4f,1);var l=Bulb(g.transform,true,4.3f,rad*1.65f);if(i==0){l.shadows=LightShadows.Soft;l.shadowBias=.015f;l.shadowNormalBias=.02f;}pendants++;}
 var angles=new List<float>();for(int i=0;i<2;i++){float best=-1,bestAngle=0;for(int a=0;a<360;a+=5){float doors=r["doors"].Min(q=>Mathf.Abs(Mathf.DeltaAngle(a,(float)q["angle"])));float sep=angles.Count==0?180:angles.Min(x=>Mathf.Abs(Mathf.DeltaAngle(a,x)));float score=doors+sep*.4f;if(doors<Mathf.Asin(Mathf.Min(.9f,3.2f/rad))*Mathf.Rad2Deg||sep<100)continue;if(score>best){best=score;bestAngle=a;}}angles.Add(bestAngle);var dir=new Vector3(Mathf.Cos(bestAngle*Mathf.Deg2Rad),0,Mathf.Sin(bestAngle*Mathf.Deg2Rad));var g=Put("B2_"+id+"_ServiceBulkhead_"+i,"BD_RoundBulkhead",lighting,center+dir*(Mathf.Sqrt(rad*rad-3.05f*3.05f)-.16f)+Vector3.up*3.05f,Quaternion.LookRotation(-dir));Bulb(g.transform,false,.95f,6.5f);wall++;}}
 Save(s);int active=s.GetRootGameObjects().Where(g=>g.name.StartsWith("B2_")).SelectMany(g=>g.GetComponentsInChildren<Light>()).Count();var result=new{upperPipeRoutes=19,before,after=active,corridorBulkheads=corridor,roomBulkheads=wall,pendants,coreBulkheads=cores};File.WriteAllText(O+"service_lighting.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
}
